import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const b=JSON.parse('{"title":"XiHan.Framework.Workflow.Abstractions","description":"","frontmatter":{},"headers":[],"relativePath":"packages/workflow-abstractions.md","filePath":"packages/workflow-abstractions.md","lastUpdated":1786268168000}'),r={name:"packages/workflow-abstractions.md"};function i(c,t,s,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="xihan-framework-workflow-abstractions" tabindex="-1">XiHan.Framework.Workflow.Abstractions <a class="header-anchor" href="#xihan-framework-workflow-abstractions" aria-label="Permalink to &quot;XiHan.Framework.Workflow.Abstractions&quot;">​</a></h1><blockquote><p>工作流抽象包：流程定义模型、活动契约、运行时实例/书签模型、存储端口与人工任务契约。<strong>不含任何执行实现。</strong></p></blockquote><ul><li><strong>NuGet</strong>：<code>XiHan.Framework.Workflow.Abstractions</code></li><li><strong>模块类</strong>：<code>XiHanWorkflowAbstractionsModule</code></li><li><strong>所在层</strong>：应用层（抽象）</li><li><strong>关键依赖</strong>：仅 <code>XiHan.Framework.Core</code></li></ul><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本包只定义<strong>契约与数据模型</strong>，让「定义流程」「实现活动」「实现存储」三件事可以独立于执行引擎完成。典型用法是：领域项目只引用本包声明流程定义与自定义活动，宿主项目才引用 <a href="./workflow">XiHan.Framework.Workflow</a> 装配引擎。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>想在不引入执行引擎的项目（如领域层、契约包）里声明流程定义或自定义活动。</li><li>想实现自己的存储后端（数据库 / Redis），只需要实现三个 Store 端口。</li><li>想把工作流事件的订阅方与引擎解耦。</li></ul><h2 id="安装与启用" tabindex="-1">安装与启用 <a class="header-anchor" href="#安装与启用" aria-label="Permalink to &quot;安装与启用&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XiHan.Framework.Workflow.Abstractions</span></span></code></pre></div><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DependsOn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XiHanWorkflowAbstractionsModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MyModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">XiHanModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { }</span></span></code></pre></div><p>模块本身不注册任何服务——它只是让本包的程序集参与模块化装配。</p><h2 id="主要-api-类型" tabindex="-1">主要 API / 类型 <a class="header-anchor" href="#主要-api-类型" aria-label="Permalink to &quot;主要 API / 类型&quot;">​</a></h2><h3 id="流程定义" tabindex="-1">流程定义 <a class="header-anchor" href="#流程定义" aria-label="Permalink to &quot;流程定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>WorkflowDefinition</code></td><td>流程定义：编码、名称、版本、状态、节点、连线、变量定义</td></tr><tr><td><code>WorkflowNode</code></td><td>节点：节点编码、活动类型编码、属性、重试策略、超时</td></tr><tr><td><code>WorkflowTransition</code></td><td>连线：来源节点、目标节点、条件表达式、是否默认分支</td></tr><tr><td><code>WorkflowVariableDefinition</code></td><td>变量定义：名称、类型、是否必填、默认值</td></tr><tr><td><code>WorkflowRetryPolicy</code></td><td>节点级重试策略</td></tr><tr><td><code>WorkflowDefinitionStatus</code></td><td><code>Draft</code>(0) 草稿 / <code>Published</code>(1) 已发布（<strong>只有已发布才能启动实例</strong>）/ <code>Disabled</code>(2) 已停用（不可启动新实例，存量实例继续运行）/ <code>Archived</code>(3) 已归档</td></tr><tr><td><code>IWorkflowDefinitionManager</code></td><td>定义生命周期门面：<code>CreateAsync</code> / <code>UpdateDraftAsync</code> / <code>PublishAsync(id)</code> / <code>CreateNewVersionAsync(code)</code> / <code>DisableAsync(id)</code> / <code>ArchiveAsync(id)</code> / <code>GetAsync(id)</code> / <code>GetPublishedAsync(code, version)</code> / <code>GetListAsync(...)</code></td></tr></tbody></table><h3 id="活动契约" tabindex="-1">活动契约 <a class="header-anchor" href="#活动契约" aria-label="Permalink to &quot;活动契约&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>IWorkflowActivity</code></td><td>活动契约：给定 <code>ActivityExecutionContext</code> 返回 <code>ActivityExecutionResult</code></td></tr><tr><td><code>IResumableWorkflowActivity</code></td><td>可恢复活动：额外实现「书签被恢复时怎么处理」（<code>ActivityResumeContext</code>）</td></tr><tr><td><code>ICompensableWorkflowActivity</code></td><td>可补偿活动：实例取消且定义启用补偿时按执行逆序回补</td></tr><tr><td><code>[WorkflowActivity]</code></td><td>标注活动的类型编码（定义里的 <code>ActivityType</code> 据此匹配）</td></tr><tr><td><code>ActivityExecutionResult</code></td><td>执行结果，<code>ActivityExecutionResultKind</code> 区分「继续 / 挂起等待书签 / 故障 / 终止」</td></tr><tr><td><code>ActivityOutgoingBehavior</code></td><td>出向行为：走哪些连线（全部 / 按条件 / 指定）</td></tr><tr><td><code>WorkflowActivityTypes</code></td><td>内置活动类型编码常量（见 <a href="./workflow#内置活动">Workflow 包</a> 列表）</td></tr></tbody></table><h3 id="运行时模型" tabindex="-1">运行时模型 <a class="header-anchor" href="#运行时模型" aria-label="Permalink to &quot;运行时模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>WorkflowInstance</code></td><td>流程实例：定义引用、状态、变量、节点实例、父实例信息</td></tr><tr><td><code>WorkflowInstanceStatus</code></td><td><code>Running</code>(1) 运行中（含等待书签的空闲态）/ <code>Suspended</code>(2) 已挂起 / <code>Completed</code>(3) / <code>Canceled</code>(4) 已取消（可触发补偿）/ <code>Faulted</code>(5) 已故障（可重试）/ <code>Terminated</code>(6) 已终止（不补偿、不可恢复）</td></tr><tr><td><code>WorkflowNodeInstance</code> / <code>WorkflowNodeInstanceStatus</code></td><td>节点实例与其状态</td></tr><tr><td><code>WorkflowBookmark</code> / <code>WorkflowBookmarkRequest</code></td><td><strong>书签</strong>：实例挂起后可被外界恢复的等待点</td></tr><tr><td><code>WorkflowBookmarkKinds</code></td><td>书签种类常量（见下表）</td></tr><tr><td><code>WorkflowJoinState</code></td><td>汇聚网关的分支到达状态</td></tr><tr><td><code>WorkflowVariables</code> / <code>WorkflowValueConverter</code></td><td>变量容器与类型转换</td></tr><tr><td><code>WorkflowStartRequest</code></td><td>启动请求：定义编码/版本、初始变量、业务相关性标识</td></tr></tbody></table><p><strong>书签种类</strong>决定恢复来源与 <code>Key</code> 的语义：</p><table tabindex="0"><thead><tr><th>种类</th><th><code>Key</code> / <code>DueTime</code> 语义</th><th>由谁恢复</th></tr></thead><tbody><tr><td><code>UserTask</code></td><td>Key = 受理人标识</td><td>人工办理</td></tr><tr><td><code>Timer</code></td><td>DueTime = 到期时间</td><td>定时器 Worker 轮询</td></tr><tr><td><code>Signal</code></td><td>Key = 信号名称</td><td><code>PublishSignalAsync</code></td></tr><tr><td><code>SubWorkflow</code></td><td>Key = 父节点实例标识</td><td>子流程终态回调</td></tr><tr><td><code>Retry</code></td><td>DueTime = 下次重试时间</td><td>定时器 Worker 轮询</td></tr><tr><td><code>NodeTimeout</code></td><td>DueTime = 节点超时时间</td><td>定时器 Worker 轮询</td></tr></tbody></table><h3 id="存储端口" tabindex="-1">存储端口 <a class="header-anchor" href="#存储端口" aria-label="Permalink to &quot;存储端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端口</th><th>职责</th></tr></thead><tbody><tr><td><code>IWorkflowDefinitionStore</code></td><td>流程定义的持久化</td></tr><tr><td><code>IWorkflowInstanceStore</code></td><td>流程实例的持久化</td></tr><tr><td><code>IWorkflowBookmarkStore</code></td><td>书签的持久化与到期检索</td></tr></tbody></table><p>实现包默认提供内存实现，业务侧可用 <code>Replace</code> 换成数据库/Redis 实现。</p><h3 id="人工任务" tabindex="-1">人工任务 <a class="header-anchor" href="#人工任务" aria-label="Permalink to &quot;人工任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>IWorkflowUserTaskService</code></td><td>待办查询与办理门面：<code>GetPendingAsync(assigneeId)</code>、<code>GetPendingByInstanceAsync(instanceId)</code>、<code>CompleteAsync(...)</code>、转办等</td></tr><tr><td><code>WorkflowUserTask</code></td><td>待办任务模型</td></tr><tr><td><code>UserTaskCompletionPolicy</code></td><td><code>Any</code>(1) 或签（任一同意即通过、任一拒绝即拒绝）/ <code>All</code>(2) 会签（全部同意才通过、任一拒绝一票否决）/ <code>Sequential</code>(3) 依次审批</td></tr><tr><td><code>WorkflowUserTaskOutcomes</code></td><td>办理结果常量：<code>approved</code> / <code>rejected</code> / <code>timeout</code>（<strong>允许自定义结果</strong>）</td></tr></tbody></table><h3 id="事件与异常" tabindex="-1">事件与异常 <a class="header-anchor" href="#事件与异常" aria-label="Permalink to &quot;事件与异常&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>WorkflowInstanceEvents</code></td><td>实例级事件（启动/完成/取消/故障等）</td></tr><tr><td><code>WorkflowNodeEvents</code></td><td>节点级事件</td></tr><tr><td><code>WorkflowUserTaskEvents</code></td><td>人工任务事件（创建/办理/转办）</td></tr><tr><td><code>WorkflowException</code></td><td>工作流基础异常</td></tr><tr><td><code>WorkflowDefinitionValidationException</code></td><td>定义校验失败（节点/连线/变量不合法）</td></tr><tr><td><code>WorkflowLockTimeoutException</code></td><td>实例锁获取超时（并发冲突）</td></tr></tbody></table><h3 id="引擎与表达式" tabindex="-1">引擎与表达式 <a class="header-anchor" href="#引擎与表达式" aria-label="Permalink to &quot;引擎与表达式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>IWorkflowEngine</code></td><td>实例生命周期统一入口（实现见 <a href="./workflow">Workflow 包</a>）</td></tr><tr><td><code>IWorkflowExpressionEvaluator</code></td><td>表达式求值端口（条件分支、变量赋值用）</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>本包<strong>没有执行能力</strong>：只引用它，流程定义能建、能校验模型，但跑不起来。执行要引 <a href="./workflow">XiHan.Framework.Workflow</a>。</li><li>定义模型是<strong>可序列化的纯数据</strong>，流程定义可以落库、从库里读回来跑，不必编译进程序集。</li><li>书签是整套挂起/恢复机制的核心：实例挂起等待期间<strong>不占用任何线程</strong>。</li></ul><h2 id="依赖模块" tabindex="-1">依赖模块 <a class="header-anchor" href="#依赖模块" aria-label="Permalink to &quot;依赖模块&quot;">​</a></h2><ul><li><a href="./core">XiHan.Framework.Core</a> — 模块化与依赖注入基础，唯一依赖。</li></ul><h2 id="相关模块" tabindex="-1">相关模块 <a class="header-anchor" href="#相关模块" aria-label="Permalink to &quot;相关模块&quot;">​</a></h2><ul><li><a href="./workflow">XiHan.Framework.Workflow</a> — 执行引擎与内置活动库。</li><li><a href="./eventbus">XiHan.Framework.EventBus</a> — 工作流事件的默认发布通道。</li></ul>`,35)])])}const p=e(r,[["render",i]]);export{b as __pageData,p as default};
